<?php

use Illuminate\Support\Facades\File;

/**
 * infrastructure/scripts/mail-identity — the reviewed mail identity of the host
 * (mail-outbound.json) and of each production target (mail-identity.json): the
 * DKIM key a target signs with, the DNS records that publish it, and the proof,
 * from the host, that public DNS says exactly that.
 *
 * Every test runs the shipped script. Keys are real, generated by OpenSSL, and
 * the public key it derives is checked against PHP's own OpenSSL binding. DNS is
 * a stub that answers in the exact presentation format `dig` prints; nothing
 * here queries the network, and nothing anywhere sends mail.
 *
 * The real tits-guru identity is reviewed here, and stays inert: tits-guru is
 * still held and planned, and the host still has direct delivery disabled.
 */
/** A refusal: non-zero, and this reason on stderr. */
function expectMailIdentityRefusal(array $run, string $reason): void
{
    expect($run['status'])->not->toBe(0, "expected a refusal for: {$reason}\n{$run['stdout']}");
    expect($run['stdout'])->toBe('', 'a refused run printed something on stdout');
    expect(str_contains($run['stderr'], $reason))->toBeTrue("refusal reason not found:\n  {$reason}\nstderr was:\n{$run['stderr']}");
}

// =============================================================================
// THE REVIEWED IDENTITY
// =============================================================================

it('validates the real host and target identity contracts', function () {
    $run = mailIdentityRun(['validate']);

    expect($run['status'])->toBe(0, $run['stderr']);
    expect($run['stdout'])->toContain('mail identity is valid');

    // mta1.tits.guru is the reviewed host identity, and direct delivery stays
    // disabled on the host.
    expect(json_decode(File::get(base_path('infrastructure/config/mail-outbound.json')), true))
        ->toBe(['schema_version' => 1, 'direct' => ['enabled' => false, 'mta_hostname' => 'mta1.tits.guru']]);

    // rg1, RSA-SHA256, 2048 bits; DMARC p=none with strict alignment, and no
    // report address anywhere.
    expect(json_decode(File::get(base_path('infrastructure/config/mail-identity.json')), true))->toBe([
        'schema_version' => 1,
        'targets' => [
            'tits-guru' => [
                'dkim' => ['selector' => 'rg1', 'algorithm' => 'rsa-sha256', 'minimum_key_bits' => 2048],
                'dmarc' => ['policy' => 'none', 'adkim' => 'strict', 'aspf' => 'strict'],
            ],
        ],
    ]);

    expect(File::get(base_path('infrastructure/config/mail-identity.json')))
        ->not->toContain('rua')
        ->not->toContain('@')
        ->not->toContain('mail_domain')
        ->not->toContain('tits.guru');
});

it('keeps the real target held and planned, and the host without an outbound route', function () {
    $registry = json_decode(File::get(base_path('infrastructure/config/deployment-targets.json')), true);
    $routing = json_decode(File::get(base_path('infrastructure/config/mail-routing.json')), true);

    expect($registry['targets']['tits-guru']['lifecycle'])->toBe('planned');
    expect($routing['targets']['tits-guru']['delivery_mode'])->toBe('held');
    expect(json_decode(File::get(base_path('infrastructure/config/mail-outbound.json')), true)['direct']['enabled'])->toBeFalse();

    // The production environment is not touched by an identity.
    foreach (['production.env.example', 'tits-guru.env.example'] as $template) {
        $values = envFileValues("infrastructure/templates/environment/{$template}");

        foreach (['MAIL_MAILER', 'MAIL_HOST', 'MAIL_PORT', 'MAIL_FROM_ADDRESS'] as $key) {
            expect($values[$key] ?? '')->toBe('', "{$template} sets {$key}");
        }
    }
});

it('derives tits-guru\'s key destination from its ID and reviewed selector, deferred while its mail is held', function () {
    $run = mailIdentityRun(['dkim-key', '--target', 'tits-guru']);

    expect($run['status'])->toBe(0, $run['stderr']);
    expect($run['stdout'])->toBe("deferred\t/etc/opendkim/keys/tits-guru/rg1.private\t2048\n");

    // A target with no production identity has no key at all.
    expect(mailIdentityRun(['dkim-key', '--target', 'staging-main'])['stdout'])->toBe("none\n");
});

it('derives a target it has never heard of the same way, and requires its key once it is outbound', function () {
    $scratch = mailIdentityScratch();

    try {
        $held = mailIdentityRun(['dkim-key', '--target', 'demo-shop', ...mailIdentityFixtureConfig($scratch.'/config')]);
        expect($held['stdout'])->toBe("deferred\t/etc/opendkim/keys/demo-shop/shop2026.private\t2048\n");

        $outbound = mailIdentityRun(['dkim-key', '--target', 'demo-shop', ...mailIdentityFixtureConfig($scratch.'/config', [
            'mode' => 'outbound',
            'outbound' => ['schema_version' => 1, 'direct' => ['enabled' => true, 'mta_hostname' => 'mta1.example.net']],
        ])]);
        expect($outbound['stdout'])->toBe("required\t/etc/opendkim/keys/demo-shop/shop2026.private\t2048\n");
    } finally {
        removeScratchDir($scratch);
    }
});

it('names no target, domain, selector or host anywhere in its implementation', function () {
    $source = File::get(mailIdentityScript());

    foreach (['tits-guru', 'tits.guru', 'rg1', 'mta1', 'demo-shop', 'staging-main', 'staging.invalid', '203.0.113'] as $name) {
        expect(str_contains($source, $name))->toBeFalse("mail-identity names {$name}");
    }

    // The policy reaches it only through mail-routing's render, and nothing from
    // a contract is ever evaluated as code.
    $code = executableSourceLines($source);
    expect($code)
        ->toContain('"${MAIL_ROUTING_CLI}" render-plan --file "${ROUTING_FILE}" --registry "${REGISTRY_FILE}"')
        ->not->toContain('eval ')
        ->not->toContain('bash -c');
});

it('changes nothing: no file, no service, no record, no mail', function () {
    $code = executableSourceLines(File::get(mailIdentityScript()));

    // Commands, as whole words: "-outform" is not rm, and "installed" in a
    // message is not install.
    foreach (['install', 'mkdir', 'chmod', 'chown', 'mv', 'rm', 'tee', 'cp', 'mktemp', 'systemctl', 'postconf', 'postfix', 'postsuper', 'sendmail', 'nsupdate', 'curl', 'wget', 'ssh', 'scp', 'sudo', 'genpkey', 'genrsa', 'req'] as $command) {
        expect(preg_match('/(?<![\w-])'.preg_quote($command, '/').'(?![\w-])/', $code))->toBe(0, "mail-identity runs {$command}");
    }

    // A key is never printed in any form: no text dump, no cat, no echo of it.
    foreach (['-text -in', 'cat "${path}"', 'cat "$1"', '-noout -text -in'] as $leak) {
        expect(str_contains($code, $leak))->toBeFalse("mail-identity could print a key with {$leak}");
    }
});

it('is repository tooling, never installed onto a host', function () {
    expect(repositoryOnlyScriptNames())->toContain('mail-identity');
    expect(requiredCliManifestNames())->not->toContain('mail-identity');
    expect(executableSourceLines(File::get(base_path('infrastructure/scripts/install-target-operations'))))
        ->not->toContain('mail-identity');
});

