it('accepts an unencrypted RSA private key of at least the reviewed size, PKCS#8 or PKCS#1', function (string $kind, int $bits) {
    $run = mailIdentityRun(['check-key', '--file', mailIdentityKey($kind)]);

    expect($run['status'])->toBe(0, $run['stderr']);
    expect($run['stdout'])->toContain("usable: an unencrypted {$bits}-bit RSA private key");
    expectNoKeyMaterial($run['stdout'].$run['stderr'], mailIdentityKey($kind));
})->with([
    'PKCS#8, 2048 bits' => ['rsa2048', 2048],
    'PKCS#1, 2048 bits' => ['rsa2048-pkcs1', 2048],
    'PKCS#8, 3072 bits' => ['rsa3072', 3072],
]);

it('refuses everything that is not a usable DKIM private key, without ever showing it', function (string $kind, string $reason) {
    $run = mailIdentityRun(['check-key', '--file', mailIdentityKey($kind)]);

    expectMailIdentityRefusal($run, "not a usable DKIM private key: {$reason}");
    expectNoKeyMaterial($run['stdout'].$run['stderr'], mailIdentityKey($kind));
})->with([
    'not PEM at all' => ['junk', 'it is not PEM'],
    'a public key' => ['public', 'it is a public key, not a private key'],
    'a certificate' => ['certificate', 'it is a certificate, not a private key'],
    'a key with a certificate beside it' => ['key-and-certificate', 'it is a certificate, not a private key'],
    'a passphrase-protected key' => ['encrypted', 'it is passphrase-protected'],
    'RSA below 2048 bits' => ['rsa1024', 'it is a 1024-bit RSA key, below the reviewed minimum of 2048 bits'],
    'an EC key' => ['ec', 'it is not a usable RSA private key'],
    'an Ed25519 key' => ['ed25519', 'it is not a usable RSA private key'],
]);

it('holds a key to the minimum the identity reviews, not merely to 2048 bits', function () {
    expectMailIdentityRefusal(
        mailIdentityRun(['check-key', '--file', mailIdentityKey('rsa2048'), '--min-bits', '3072']),
        'it is a 2048-bit RSA key, below the reviewed minimum of 3072 bits',
    );
    expect(mailIdentityRun(['check-key', '--file', mailIdentityKey('rsa3072'), '--min-bits', '3072'])['status'])->toBe(0);
});

it('refuses a key reached through a symlink, or that is not a regular file', function () {
    $scratch = mailIdentityScratch();

    try {
        symlink(mailIdentityKey('rsa2048'), $scratch.'/link.pem');

        expectMailIdentityRefusal(mailIdentityRun(['check-key', '--file', $scratch.'/link.pem']), 'it is a symlink');
        expectMailIdentityRefusal(mailIdentityRun(['check-key', '--file', $scratch.'/fs']), 'it is not a regular file');
        expectMailIdentityRefusal(mailIdentityRun(['check-key', '--file', $scratch.'/absent.pem']), 'it does not exist');
    } finally {
        removeScratchDir($scratch);
    }
});

// =============================================================================
// THE DNS TO PUBLISH
// =============================================================================

it('prints exactly the records to publish, deriving the DKIM public key from the installed private key', function () {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $env = mailIdentityDnsHost($scratch, []);

        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru'], $env);
        expect($run['status'])->toBe(0, $run['stderr']);

        $text = preg_replace('/\s+/', ' ', $run['stdout']);
        $public = mailIdentityPublicKey($key);

        expect($text)
            ->toContain('hostname mta1.tits.guru (direct delivery disabled on this host)')
            ->toContain('A mta1.tits.guru -> 203.0.113.10')
            ->toContain('PTR 203.0.113.10 -> mta1.tits.guru')
            ->toContain('TXT rg1._domainkey.tits.guru v=DKIM1; k=rsa; p='.$public)
            ->toContain('TXT tits.guru v=spf1 ip4:203.0.113.10 -all')
            ->toContain('TXT _dmarc.tits.guru v=DMARC1; p=none; adkim=s; aspf=s');

        expectNoKeyMaterial($run['stdout'].$run['stderr'], $key);

        // Deterministic: the same key and host print the same plan.
        expect(mailIdentityRun(['show-dns', '--target', 'tits-guru'], $env)['stdout'])->toBe($run['stdout']);
    } finally {
        removeScratchDir($scratch);
    }
});

it('prints the same records as JSON, with nothing but public values', function () {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru', '--json'], mailIdentityDnsHost($scratch, []));

        expect($run['status'])->toBe(0, $run['stderr']);
        $plan = json_decode($run['stdout'], true, 512, JSON_THROW_ON_ERROR);

        expect($plan['mta'])->toBe(['direct_delivery_enabled' => false, 'hostname' => 'mta1.tits.guru', 'ipv4' => '203.0.113.10']);
        expect($plan['dkim']['key_status'])->toBe('usable');
        expect($plan['records'])->toBe([
            ['name' => 'mta1.tits.guru', 'purpose' => 'A', 'type' => 'A', 'value' => '203.0.113.10'],
            ['name' => '203.0.113.10', 'purpose' => 'PTR', 'type' => 'PTR', 'value' => 'mta1.tits.guru'],
            ['name' => 'rg1._domainkey.tits.guru', 'purpose' => 'DKIM', 'type' => 'TXT', 'value' => 'v=DKIM1; k=rsa; p='.mailIdentityPublicKey($key)],
            ['name' => 'tits.guru', 'purpose' => 'SPF', 'type' => 'TXT', 'value' => 'v=spf1 ip4:203.0.113.10 -all'],
            ['name' => '_dmarc.tits.guru', 'purpose' => 'DMARC', 'type' => 'TXT', 'value' => 'v=DMARC1; p=none; adkim=s; aspf=s'],
        ]);

        expectNoKeyMaterial($run['stdout'], $key);
    } finally {
        removeScratchDir($scratch);
    }
});

it('says in its JSON whether the key is usable, absent or unusable, and leaves an underivable value empty', function () {
    $scratch = mailIdentityScratch();

    try {
        $plan = fn (): array => json_decode(mailIdentityRun(['show-dns', '--target', 'tits-guru', '--json'], mailIdentityDnsHost($scratch, []))['stdout'], true, 512, JSON_THROW_ON_ERROR);
        $dkim = fn (array $plan): mixed => collect($plan['records'])->firstWhere('purpose', 'DKIM')['value'];

        expect($plan()['dkim']['key_status'])->toBe('absent')
            ->and($dkim($plan()))->toBeNull();

        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        file_put_contents($key, (string) file_get_contents(mailIdentityKey('rsa1024')));

        expect($plan()['dkim']['key_status'])->toBe('unusable')
            ->and($dkim($plan()))->toBeNull();

        file_put_contents($key, (string) file_get_contents(mailIdentityKey('rsa2048')));

        expect($plan()['dkim']['key_status'])->toBe('usable')
            ->and($dkim($plan()))->toStartWith('v=DKIM1; k=rsa; p=');
    } finally {
        removeScratchDir($scratch);
    }
});

it('derives the public key from a key the operator holds, before it is installed anywhere', function () {
    // The order an operator works in: create the key, publish its public half,
    // then supply it. show-dns reads a key file named on the command line and
    // still prints only the public half.
    $scratch = mailIdentityScratch();

    try {
        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru', '--key', mailIdentityKey('rsa2048-pkcs1'), '--ipv4', '198.51.100.7']);

        expect($run['status'])->toBe(0, $run['stderr']);
        expect(preg_replace('/\s+/', ' ', $run['stdout']))
            ->toContain('p='.mailIdentityPublicKey(mailIdentityKey('rsa2048')))
            ->toContain('v=spf1 ip4:198.51.100.7 -all');
        expectNoKeyMaterial($run['stdout'].$run['stderr'], mailIdentityKey('rsa2048-pkcs1'));
    } finally {
        removeScratchDir($scratch);
    }
});

it('says what is still pending instead of inventing a key or an address', function () {
    $scratch = mailIdentityScratch();

    try {
        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, [], null));

        expect($run['status'])->toBe(0, $run['stderr']);
        expect($run['stdout'])
            ->toContain('<pending: the installed key /etc/opendkim/keys/tits-guru/rg1.private is not usable — it does not exist>')
            ->toContain('<this host IPv4: run on the mail host, or pass --ipv4>')
            ->not->toContain('v=DKIM1');

        // A weak key is named as such, and never published.
        mailIdentityInstallKey($scratch, 'tits-guru', 'rg1', 'rsa1024');
        expect(mailIdentityRun(['show-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, []))['stdout'])
            ->toContain('below the reviewed minimum of 2048 bits')
            ->not->toContain('v=DKIM1; k=rsa; p=');

        expectMailIdentityRefusal(mailIdentityRun(['show-dns', '--target', 'staging-main']), 'staging-main has no mail identity');
    } finally {
        removeScratchDir($scratch);
    }
});

// =============================================================================
// VERIFYING PUBLIC DNS
// =============================================================================

it('verifies correctly published DNS, joining a long DKIM record a provider split into chunks', function () {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $dns = mailIdentityGoodDns(mailIdentityPublicKey($key));

        // Proof the record really is split, with whitespace between the chunks.
        expect(substr_count($dns['TXT rg1._domainkey.tits.guru'][0], '" "'))->toBeGreaterThan(0);

        $run = mailIdentityRun(['verify-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, $dns));

        expect($run['status'])->toBe(0, $run['stdout'].$run['stderr']);
        expect($run['stdout'])
            ->toContain('PASS   a          mta1.tits.guru A includes this host\'s address 203.0.113.10')
            ->toContain('PASS   ptr        203.0.113.10 PTR is mta1.tits.guru')
            ->toContain('PASS   spf        tits.guru SPF authorizes exactly this host (203.0.113.10) and fails everything else')
            ->toContain('PASS   dkim       rg1._domainkey.tits.guru publishes exactly the public key of the installed private key')
            ->toContain('PASS   dmarc      _dmarc.tits.guru publishes exactly the reviewed policy')
            ->toContain('DNS VERIFIED: YES');
        expectNoKeyMaterial($run['stdout'].$run['stderr'], $key);
    } finally {
        removeScratchDir($scratch);
    }
});

