});

it('refuses every way public DNS can disagree with the reviewed identity', function (array $changes, string|false|null $ipv4, string $check, string $reason) {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $dns = mailIdentityGoodDns(mailIdentityPublicKey($key));

        // Each change replaces one answer whole; null removes it, and
        // OTHER_KEY stands for the public key of a different private key.
        foreach ($changes as $question => $answer) {
            if ($answer === null) {
                unset($dns[$question]);

                continue;
            }

            $dns[$question] = array_map(
                static fn (mixed $value): mixed => is_string($value) ? str_replace('OTHER_KEY', mailIdentityPublicKey(mailIdentityKey('rsa3072')), $value) : $value,
                $answer,
            );
        }

        $run = mailIdentityRun(
            ['verify-dns', '--target', 'tits-guru'],
            mailIdentityDnsHost($scratch, $dns, $ipv4 === false ? '203.0.113.10' : $ipv4),
        );

        expect($run['status'])->not->toBe(0, $run['stdout']);
        expect($run['stdout'])
            ->toMatch('/^  FAIL   '.preg_quote($check, '/').' +.*'.preg_quote($reason, '/').'/m')
            ->toContain('DNS VERIFIED: NO')
            ->not->toContain('DNS VERIFIED: YES');
        expectNoKeyMaterial($run['stdout'].$run['stderr'], $key);
    } finally {
        removeScratchDir($scratch);
    }
})->with([
    'an A record elsewhere' => [['A mta1.tits.guru' => ['198.51.100.9']], false, 'a', 'mta1.tits.guru A is [198.51.100.9], which does not include this host\'s address 203.0.113.10'],
    'no A record' => [['A mta1.tits.guru' => null], false, 'a', 'mta1.tits.guru has no A record (NXDOMAIN)'],
    'a PTR naming something else' => [['PTR 10.113.0.203.in-addr.arpa' => ['ip-203-0-113-10.provider.example.']], false, 'ptr', '203.0.113.10 PTR is ip-203-0-113-10.provider.example, not mta1.tits.guru'],
    'no PTR' => [['PTR 10.113.0.203.in-addr.arpa' => null], false, 'ptr', '203.0.113.10 has no PTR record'],
    'two PTR records' => [['PTR 10.113.0.203.in-addr.arpa' => ['mta1.tits.guru.', 'other.example.']], false, 'ptr', 'has 2 PTR records'],
    'two SPF policies' => [['TXT tits.guru' => ['"v=spf1 ip4:203.0.113.10 -all"', '"v=spf1 include:_spf.provider.example ~all"']], false, 'spf', 'tits.guru publishes 2 SPF policies — receivers treat more than one as a permanent error'],
    'no SPF policy' => [['TXT tits.guru' => ['"site-verification=abc123"']], false, 'spf', 'tits.guru publishes no SPF policy — publish exactly one TXT record: v=spf1 ip4:203.0.113.10 -all'],
    'a soft-failing SPF' => [['TXT tits.guru' => ['"v=spf1 ip4:203.0.113.10 ~all"']], false, 'spf', 'tits.guru SPF is "v=spf1 ip4:203.0.113.10 ~all", not the reviewed'],
    'SPF for another address' => [['TXT tits.guru' => ['"v=spf1 ip4:198.51.100.9 -all"']], false, 'spf', 'not the reviewed "v=spf1 ip4:203.0.113.10 -all"'],
    'a DKIM record for another key' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; k=rsa; p=OTHER_KEY"']], false, 'dkim', 'publishes a different public key than the installed private key derives'],
    'no DKIM record' => [['TXT rg1._domainkey.tits.guru' => null], false, 'dkim', 'rg1._domainkey.tits.guru has no TXT record'],
    'a DKIM record of another key type' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; k=ed25519; p=abc"']], false, 'dkim', 'rg1._domainkey.tits.guru has k=ed25519, not k=rsa'],
    'a DKIM record in testing mode' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; t=y; k=rsa; p=abc"']], false, 'dkim', 'must carry exactly the tags v, k and p, found: k p t v'],
    'two DKIM records' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; k=rsa; p=OTHER_KEY"', '"v=DKIM1; k=rsa; p=abc"']], false, 'dkim', 'has 2 TXT records — a selector publishes exactly one key'],
