            ->toContain('FAIL   signing    staging-main has no reviewed signing identity, so nothing on this host signs its mail')
            ->toContain('OUTBOUND READY: NO');
        expect(mailIdentitySigningCalls($scratch))->toBe([]);
    } finally {
